package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.atomic.*;
public class BackgroundPlaybackTest extends Instrumentation {
    MainActivity current;
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean done=new AtomicBoolean();ui(()->done.set(predicate.getAsBoolean()));if(done.get())return;Thread.sleep(40);}String[] state={""};ui(()->{if(current!=null)state[0]=" status="+current.status.getText()+" playing="+current.playing+" completed="+current.completedBooks+" position="+current.position+" loop="+current.loopPlayback;});throw new AssertionError(message+state[0]);}
    void book(MainActivity a,String text){a.stop();a.text=text;a.chapters=MainActivity.parse(text);a.chapter=0;a.position=0;a.showPosition(true);a.readingLanguage="";a.systemVoiceKey="";a.offlineVoice=1000;a.rate=2f;}
    void shell(String command)throws Exception{try(java.io.InputStream output=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] buffer=new byte[256];while(output.read(buffer)!=-1){}}Thread.sleep(400);}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;SharedPreferences preferences=getTargetContext().getSharedPreferences("reading_settings",0);boolean hadMode=preferences.contains("loopPlayback"),oldMode=preferences.getBoolean("loopPlayback",false);try{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","background_qa").putExtra("book_name","后台播放验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;current=a;await(()->a.offlineReady,"offline voice not ready");
        ui(()->{book(a,"读书。\n");a.loopPlayback=false;a.playbackMode.performClick();check(a.loopPlayback,"mode toggle did not enable loop");check(((android.view.ViewGroup)a.playbackMode.getParent()).getChildAt(((android.view.ViewGroup)a.playbackMode.getParent()).getChildCount()-1)==a.playbackMode,"mode button not rightmost");a.startReading();});await(()->a.completedBooks>=3,"natural end did not repeat whole book");ui(()->{check(a.playing&&PlaybackService.active!=null,"loop lost foreground service");a.stop();a.playbackMode.performClick();check(!a.loopPlayback,"mode toggle did not restore sequence");book(a,"结束。\n");a.startReading();});await(()->!a.playing&&a.status.getText().toString().equals("全书朗读完毕"),"sequence did not stop at whole-book end");await(()->PlaybackService.active==null,"foreground service leaked after completion");result.putBoolean("sequentialAndNaturalLoop",true);
        ui(()->{StringBuilder longBook=new StringBuilder("第一章 长时间后台朗读\n");for(int i=0;i<250;i++)longBook.append("这是后台连续朗读验证，锁屏后也要继续播放，保持声音和文字进度前进。\n");book(a,longBook.toString());a.startReading();});await(()->PlaybackService.active!=null&&PlaybackService.active.session.isActive()&&a.position>10,"foreground playback did not start");
        shell("input keyevent 3");shell("input keyevent 223");check(!getTargetContext().getSystemService(PowerManager.class).isInteractive(),"screen did not turn off");int[] previous={0};ui(()->previous[0]=a.position);long until=SystemClock.elapsedRealtime()+75000;int checks=0;while(SystemClock.elapsedRealtime()<until){Thread.sleep(15000);ui(()->{check(a.playing,"playback stopped with screen off: "+a.status.getText());check(PlaybackService.active!=null&&PlaybackService.active.session.isActive(),"foreground wake protection lost");check(a.position>previous[0],"background reading stalled");previous[0]=a.position;});checks++;Bundle progress=new Bundle();progress.putInt("screenOffProgressChecks",checks);sendStatus(1,progress);}
        final PlaybackService[] service={null};ui(()->service[0]=PlaybackService.active);getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction(PlaybackService.PAUSE));await(()->!a.playing&&PlaybackService.active!=null&&!PlaybackService.active.foreground,"notification pause failed");check(!service[0].wake.isHeld(),"wake lock leaked after pause");result.putBoolean("screenOff75Seconds",true);result.putBoolean("notificationPauseReleasesWakeLock",true);result.putString("result","PASS: sequential end; 3 natural whole-book loops; rightmost mode switch; 75 seconds Home+screen off with progress every 15 seconds; media foreground service and wake lock; notification pause and cleanup");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{try{shell("input keyevent 224");}catch(Exception ignored){}if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}SharedPreferences.Editor edit=preferences.edit();if(hadMode)edit.putBoolean("loopPlayback",oldMode);else edit.remove("loopPlayback");edit.commit();getTargetContext().getSharedPreferences("reader_background_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}




